Here's a greedy line-wrapping implementation that breaks only on spaces and never splits words.

```python
# file: solution.py
def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")
    words = text.split()  # collapses multiple spaces, handles tabs/newlines
    lines: list[str] = []
    current = ""
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
```

