Here's a `validate_config` that checks each schema entry for missing required keys and type mismatches (with careful handling of `bool` vs `int`, since `bool` subclasses `int` in Python), returning human-readable error strings.

```python
# file: solution.py
"""Simple schema-based validation for dict configs loaded from JSON."""

from typing import Any


def validate_config(cfg: dict, schema: dict) -> list[str]:
    """Validate ``cfg`` against ``schema``.

    ``schema`` maps a key name to a ``(type, required)`` tuple, e.g.::

        schema = {
            "host": (str, True),
            "port": (int, True),
            "debug": (bool, False),
        }

    Returns a list of human-readable error strings; an empty list means
    the config is valid.

    Rules:
      * A required key that is missing produces an error.
      * A present key whose value is not an instance of the declared type
        produces an error (value type errors only; ``None`` counts as a
        wrong type unless the schema allows it).
      * ``bool`` is *not* accepted where ``int`` is declared (and vice
        versa), even though ``bool`` subclasses ``int`` in Python.
      * Missing optional keys and extra unknown keys are allowed.
    """
    errors: list[str] = []

    if not isinstance(cfg, dict):
        return [f"config must be a dict, got {type(cfg).__name__}"]

    for key, spec in schema.items():
        try:
            expected_type, required = spec
        except (TypeError, ValueError):
            errors.append(
                f"invalid schema entry for {key!r}: "
                f"expected a (type, required) tuple, got {spec!r}"
            )
            continue

        if key not in cfg:
            if required:
                errors.append(f"missing required key: {key!r}")
            continue

        value = cfg[key]
        if not _type_matches(value, expected_type):
            errors.append(
                f"key {key!r} must be of type {_type_name(expected_type)}, "
                f"got {type(value).__name__} (value: {value!r})"
            )

    return errors


def _type_matches(value: Any, expected: Any) -> bool:
    """Check type membership with special bool/int handling."""
    # bool is a subclass of int; treat them as distinct unless the
    # schema explicitly allows both via a tuple like (int, bool).
    if expected is int and isinstance(value, bool):
        return False
    if expected is bool and isinstance(value, int) and not isinstance(value, bool):
        return False
    return isinstance(value, expected)


def _type_name(expected: Any) -> str:
    """Human-readable name for a type or tuple of types."""
    if isinstance(expected, tuple):
        return " or ".join(t.__name__ for t in expected)
    return getattr(expected, "__name__", repr(expected))
```

