```python
# file: solution.py
import re

_TOKEN_RE = re.compile(r"(\d+)\s*(h|m|s)")

_UNIT_SECONDS = {"h": 3600, "m": 60, "s": 1}


def parse_duration(s: str) -> int:
    """Parse a duration string like "1h30m" or "45 s" into total seconds.

    Components may appear in any order and may be separated by whitespace.
    Raises ValueError for empty input, unknown units, or leftover text.
    """
    if not isinstance(s, str) or not s.strip():
        raise ValueError("duration string must be non-empty")

    total = 0
    consumed = ""
    for match in _TOKEN_RE.finditer(s):
        value, unit = match.groups()
        total += int(value) * _UNIT_SECONDS[unit]
        consumed += match.group(0)

    leftover = _TOKEN_RE.sub("", s)
    if not consumed or leftover.strip():
        raise ValueError(f"invalid duration string: {s!r}")

    return total
```

