Here's a clean RingBuffer implementation with a pytest suite.

```python
# file: solution.py
"""A fixed-capacity ring buffer with overwrite-on-full semantics."""

from typing import Generic, Iterator, List, TypeVar

T = TypeVar("T")


class RingBuffer(Generic[T]):
    """Fixed-capacity FIFO buffer.

    Appending to a full buffer overwrites the oldest item.
    """

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data: List[T] = []
        self._start = 0

    @property
    def capacity(self) -> int:
        return self._capacity

    def append(self, item: T) -> None:
        """Add an item; overwrite the oldest if the buffer is full."""
        if len(self._data) < self._capacity:
            self._data.append(item)
        else:
            self._data[self._start] = item
            self._start = (self._start + 1) % self._capacity

    def pop(self) -> T:
        """Remove and return the oldest item."""
        if not self._data:
            raise IndexError("pop from empty RingBuffer")
        item = self._data[self._start]
        if self._start == len(self._data) - 1 and self._start != 0:
            self._data.pop()
            self._start = 0
        elif self._start == 0 and self._is_contiguous():
            self._data.pop(0)
        else:
            self._data[self._start] = self._data[-1]
            self._data.pop()
            if self._start >= len(self._data):
                self._start = 0
        return item

    def _is_contiguous(self) -> bool:
        return self._start == 0

    def __len__(self) -> int:
        return len(self._data)

    def to_list(self) -> List[T]:
        """Return items oldest-first."""
        if self._start == 0:
            return list(self._data)
        return self._data[self._start:] + self._data[:self._start]
```

