from typing import Any


def validate_config(cfg: dict[str, Any], schema: dict[str, tuple[type, bool]]) -> list[str]:
    """Validate a config mapping against a key -> (type, required) schema.

    Returns human-readable errors in schema iteration order. Unknown keys are
    ignored; optional absent keys are skipped; present values must match the
    declared type exactly.
    """
    errors: list[str] = []

    for key, (expected_type, required) in schema.items():
        if key not in cfg:
            if required:
                errors.append(f"missing required key '{key}'")
            continue

        value = cfg[key]
        actual_type = type(value)
        if actual_type is not expected_type:
            errors.append(
                f"key '{key}' must be of type {expected_type.__name__}, "
                f"got {actual_type.__name__}"
            )

    return errors
