Here's a `group_sum` that groups records by a key, sums a numeric field (parsing CSV-style string values), and counts rows per group. Values that can't be parsed as numbers (like empty cells or `None`) are treated as 0 but still count toward the row count.

```python
# file: solution.py
def _parse_number(value):
    """Convert a value to a number. Unparseable/empty values become 0."""
    if value is None:
        return 0
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return 0
        try:
            return int(text)
        except ValueError:
            try:
                return float(text)
            except ValueError:
                return 0
    return 0


def group_sum(records, by, field):
    """
    Group a list of dicts by the `by` key.

    Returns a dict mapping each group value to
    {'sum': <numeric sum of field>, 'count': <number of rows>}.
    """
    result = {}
    for record in records:
        key = record[by]
        value = _parse_number(record.get(field))
        if key not in result:
            result[key] = {"sum": 0, "count": 0}
        result[key]["sum"] += value
        result[key]["count"] += 1
    return result
```

