```python
# file: solution.py
from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any, Mapping, Iterable, Union

Number = Union[int, float]


def _parse_number(value: Any) -> Decimal:
    if isinstance(value, bool):
        raise ValueError("boolean values are not numeric")
    if isinstance(value, (int, float, Decimal)):
        return Decimal(str(value))
    if isinstance(value, str):
        cleaned = value.strip().replace(",", "")
        if not cleaned:
            raise ValueError("empty numeric field")
        try:
            return Decimal(cleaned)
        except InvalidOperation as exc:
            raise ValueError(f"invalid numeric value: {value!r}") from exc
    raise ValueError(f"unsupported numeric value: {value!r}")


def _display_number(value: Decimal) -> Number:
    if value == value.to_integral_value():
        return int(value)
    return float(value)


def group_sum(
    records: Iterable[Mapping[str, Any]],
    by: str,
    field: str,
) -> dict[Any, dict[str, Number]]:
    """Group records by ``by`` and aggregate ``field`` per group.

    Returns a mapping of group value to ``{"sum": total, "count": n}``.
    Numeric strings commonly produced by CSV readers are accepted.
    Missing keys raise ``KeyError``; unparseable values raise ``ValueError``.
    """
    totals: dict[Any, Decimal] = {}
    counts: dict[Any, int] = {}

    for row in records:
        if by not in row:
            raise KeyError(f"missing group key: {by!r}")
        if field not in row:
            raise KeyError(f"missing numeric field: {field!r}")

        group = row[by]
        amount = _parse_number(row[field])
        totals[group] = totals.get(group, Decimal("0")) + amount
        counts[group] = counts.get(group, 0) + 1

    return {
        group: {"sum": _display_number(totals[group]), "count": counts[group]}
        for group in totals
    }
```

