Here's the coupon logic with `min_spend` gating, percent/fixed discounts, cent rounding, and a zero floor.

```python
# file: solution.py
def apply_coupon(subtotal, coupon):
    """Apply a coupon to a subtotal.

    coupon: dict with 'type' ('percent' or 'fixed'), 'value',
            and optional 'min_spend'. If the subtotal is below
            min_spend, the coupon does not apply.
    Returns the new total rounded to cents, never below zero.
    """
    if subtotal < 0:
        raise ValueError("subtotal cannot be negative")

    min_spend = coupon.get("min_spend", 0)
    if subtotal < min_spend:
        return round(subtotal, 2)

    ctype = coupon["type"]
    value = coupon["value"]

    if ctype == "percent":
        if not 0 <= value <= 100:
            raise ValueError("percent value must be between 0 and 100")
        total = subtotal * (1 - value / 100)
    elif ctype == "fixed":
        total = subtotal - value
    else:
        raise ValueError(f"unknown coupon type: {ctype!r}")

    return max(round(total, 2), 0.0)
```

