"""Coupon application logic for checkout totals."""

from typing import TypedDict, Optional


class Coupon(TypedDict, total=False):
    type: str          # 'percent' or 'fixed'
    value: float
    min_spend: Optional[float]


def apply_coupon(subtotal: float, coupon: Coupon) -> float:
    """Apply a coupon to a subtotal and return the new total.

    The coupon is ignored if the subtotal does not meet the optional
    ``min_spend`` threshold. The result is rounded to cents and never
    negative.
    """
    if subtotal < coupon.get("min_spend", 0):
        return round(subtotal, 2)

    if coupon["type"] == "percent":
        total = subtotal * (1 - coupon["value"] / 100)
    elif coupon["type"] == "fixed":
        total = subtotal - coupon["value"]
    else:
        raise ValueError(f"Unknown coupon type: {coupon['type']}")

    return round(max(total, 0.0), 2)
