Here's an implementation that counts weekdays between two dates (inclusive), skipping holidays:

```python
# file: solution.py
from datetime import date, timedelta


def business_days_between(start: date, end: date, holidays: set[date] | None = None) -> int:
    """Count business days (Mon-Fri) from start to end, inclusive, excluding holidays.

    If start is after end, returns the negative of the count in that range.
    """
    if holidays is None:
        holidays = set()

    if start > end:
        return -business_days_between(end, start, holidays)

    count = 0
    current = start
    one_day = timedelta(days=1)
    while current <= end:
        if current.weekday() < 5 and current not in holidays:
            count += 1
        current += one_day
    return count
```

