Here's a recursive flattener that handles nested dicts and lists with the key conventions you described.

```python
# file: solution.py
def flatten_record(record, sep='.'):
    """
    Flatten a nested dict/list structure into a single-level dict.

    - Nested dict keys are joined with `sep` (e.g. {"a": {"b": 1}} -> {"a.b": 1})
    - List items get indexed keys (e.g. {"tags": ["x", "y"]} -> {"tags.0": "x", "tags.1": "y"})
    - Scalars are kept as-is.
    """
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")

    flat = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            if not value:
                flat[prefix] = value  # preserve empty dicts
            for key, sub in value.items():
                new_key = f"{prefix}{sep}{key}" if prefix else str(key)
                _flatten(sub, new_key)
        elif isinstance(value, (list, tuple)):
            if not value:
                flat[prefix] = value  # preserve empty lists
            for i, item in enumerate(value):
                _flatten(item, f"{prefix}{sep}{i}")
        else:
            flat[prefix] = value

    _flatten(record, "")
    return flat
```

