```python
# file: solution.py
import math


def round_sig(x: float, n: int = 3) -> float:
    """Round x to n significant figures and return a float."""
    if x == 0:
        return 0.0
    return round(x, -int(math.floor(math.log10(abs(x)))) + (n - 1))
