    def test_release_returns_units_to_available(self, inv):
        inv.reserve("SKU-1", 4)
        inv.release("SKU-1", 3)
        assert inv.available("SKU-1") == 9
        assert inv.reserved("SKU-1") == 1
        assert inv.on_hand("SKU-1") == 10

    def test_release_more_than_reserved_raises(self, inv):
        inv.reserve("SKU-1", 2)
        with pytest.raises(InventoryError):
            inv.release("SKU-1", 3)

    def test_release_with_nothing_reserved_raises(self, inv):
        with pytest.raises(InventoryError):
            inv.release("SKU-1", 1)


class TestCommit:
    def test_commit_removes_units_from_on_hand(self, inv):
        inv.reserve("SKU-1", 4)
        inv.commit("SKU-1", 4)
        assert inv.on_hand("SKU-1") == 6
        assert inv.available("SKU-1") == 6
        assert inv.reserved("SKU-1") == 0

    def test_partial_commit(self, inv):
        inv.reserve("SKU-1", 5)
        inv.commit("SKU-1", 2)
        assert inv.on_hand("SKU-1") == 8
        assert inv.reserved("SKU-1") == 3
        assert inv.available("SKU-1") == 5

    def test_commit_unreserved_units_raises(self, inv):
        with pytest.raises(InventoryError):
            inv.commit("SKU-1", 1)

    def test_commit_more_than_reserved_raises(self, inv):
        inv.reserve("SKU-1", 2)
        with pytest.raises(InventoryError):
            inv.commit("SKU-1", 3)


class TestWorkflow:
    def test_full_lifecycle(self, inv):
        inv.reserve("SKU-1", 6)          # 4 available, 6 reserved
        inv.release("SKU-1", 2)          # 6 available, 4 reserved
        inv.commit("SKU-1", 4)           # ship 4
        assert inv.on_hand("SKU-1") == 6
        assert inv.available("SKU-1") == 6
        assert inv.reserved("SKU-1") == 0

    def test_skus_are_independent(self, inv):
        inv.reserve("SKU-1", 10)
        assert inv.available("SKU-2") == 5
```

Key behavior: `reserve` moves units from "available" to "reserved" while keeping them on hand; `release` moves them back; `commit` deducts reserved units from on-hand stock entirely (e.g., when an order ships). Over-reservation, over-release, and over-commit all raise `InventoryError`, and quantities must be positive integers.

