```python
# file: solution.py
"""Temperature conversion between Celsius, Fahrenheit, and Kelvin."""
from typing import Union

Number = Union[int, float]

_OFFSETS = {"C": 0.0, "F": 32.0, "K": 273.15}


def _to_celsius(value: Number, unit: str) -> float:
    if unit == "C":
        return float(value)
    if unit == "F":
        return (value - 32.0) * 5.0 / 9.0
    if unit == "K":
        return value - 273.15
    raise ValueError(f"Unsupported unit: {unit!r}")


def _from_celsius(value: float, unit: str) -> float:
    if unit == "C":
        return value
    if unit == "F":
        return value * 9.0 / 5.0 + 32.0
    if unit == "K":
        return value + 273.15
    raise ValueError(f"Unsupported unit: {unit!r}")


def convert_temp(value: Number, from_unit: str, to_unit: str) -> float:
    """Convert ``value`` from ``from_unit`` to ``to_unit``.

    Units are 'C', 'F', or 'K' (case-insensitive). Returns a float.
    """
    src = from_unit.strip().upper()
    dst = to_unit.strip().upper()
    return _from_celsius(_to_celsius(value, src), dst)
