# file: solution.py
from pathlib import Path, PurePosixPath
import tarfile


class UnsafeArchiveError(RuntimeError):
    """Raised when an archive member would escape target_dir."""


def _is_contained(root: Path, path: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _safe_members(archive: tarfile.TarFile, root: Path):
    for member in archive:
        name = member.name
        parts = PurePosixPath(name).parts

        if not name or name.startswith("/") or ".." in parts:
            raise UnsafeArchiveError(f"Unsafe archive path: {name!r}")

        destination = (root / name).resolve()
        if not _is_contained(root, destination):
            raise UnsafeArchiveError(f"Archive member escapes target_dir: {name!r}")

        if member.issym() or member.islnk():
            link_name = member.linkname
            link_parts = PurePosixPath(link_name).parts
            link_destination = (destination.parent / link_name).resolve()
            if link_name.startswith("/") or not _is_contained(root, link_destination):
                raise UnsafeArchiveError(
                    f"Unsafe link target for {name!r}: {link_name!r}"
                )

        yield member


def restore_backup(archive_path, target_dir, force=False):
    """
    Extract a .tar.gz backup into target_dir.

    If target_dir exists and is non-empty, extraction is refused unless
    force=True. With force=True, existing files with the same paths may be
    overwritten; unrelated extra files are left in place.
    """
    archive_path = Path(archive_path)
    target_dir = Path(target_dir)

    if not archive_path.is_file():
        raise FileNotFoundError(f"Backup archive not found: {archive_path}")

    if target_dir.exists():
        if not target_dir.is_dir():
            raise NotADirectoryError(f"target_dir is not a directory: {target_dir}")
        if not force and any(target_dir.iterdir()):
            raise FileExistsError(
                f"Refusing to clobber non-empty directory: {target_dir}"
            )
    else:
        target_dir.mkdir(parents=True)

    root = target_dir.resolve()
    with tarfile.open(archive_path, mode="r:gz") as archive:
        archive.extractall(root, members=_safe_members(archive, root))
```

